"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["51876"],{86656(e){e.exports=JSON.parse('{"id":"FIN-795","slug":"sales-tax","term":"Sales Tax","also_known_as":[],"difficulty":"Beginner","definition":"A sales tax is a tax charged on the sale of goods and services, usually calculated as a percentage of the purchase price and collected by the seller at the point of sale.","explanation":["Sales tax is a consumption tax, paid by consumers when they buy things. Unlike value-added tax, which is collected at every stage of production, a traditional sales tax is usually charged only once, at the final sale to the consumer.","Sales taxes are especially associated with the United States, where there is no national sales tax, but most states, and many cities and counties, impose their own. Rates vary considerably by location, and prices displayed in shops typically do not include the tax, which is added at the till. In many other countries, VAT or goods and services tax is used instead, and is usually included in displayed prices.","For example, an item priced at 100 in a place with a combined sales tax rate of 8% would cost 108 at checkout.","Sales taxes are a significant source of revenue for many governments. They are generally considered regressive, because lower-income households spend a larger share of their income on taxable goods. Many jurisdictions exempt essentials such as groceries or prescription medicines to reduce this effect."],"note":"","total":1725,"prev":{"slug":"safe-withdrawal-rate","term":"Safe Withdrawal Rate"},"next":{"slug":"sample","term":"Sample"}}')}}]);